excels.excel:

EXPORT WITH SHEET="质量检验缺陷记录", HEADER=true,
    MAPPING={"a":"批次号","b":"产品名称","c":"抽检数量","d":"缺陷数量","e":"缺陷率","f":"判定"},
    FORMAT={"c":"0","d":"0","e":"0.00%"},
    FORMULAS={
        E2:'D2/C2',E3:'D3/C3',E4:'D4/C4',E5:'D5/C5',E6:'D6/C6',
        C7:'SUM(C2:C6)',D7:'SUM(D2:D6)',E7:'D7/C7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E4:{color:red,bold:true},
        E6:{color:red,bold:true}
    }
